# Frozenprepared tool is generated by source-aware host staging; no CAD launch.
import json,hashlib
from pathlib import Path
H=Path(__file__).resolve().parent;P=json.loads((H/'prepared.json').read_text())
for n,d in {**P['source_sha256'],**P['tool_sha256']}.items():assert hashlib.sha256(Path(n).read_bytes()).hexdigest()==d,n
print(hashlib.sha256((H/'prepared.json').read_bytes()).hexdigest())
